diff --git a/sql/sql_connect.cc b/sql/sql_connect.cc
index 4dab599f52d1..23c3a4cee13c 100644
--- a/sql/sql_connect.cc
+++ b/sql/sql_connect.cc
@@ -1,5 +1,5 @@
 /*
